import{_ as o,l as r,o as e,c as n,v as l,p as s,x as c,d as i,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"jemalloc / tcmalloc 竞技场","description":"","frontmatter":{"title":"jemalloc / tcmalloc 竞技场","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arena-allocators.md","filePath":"cs/arena-allocators.md","lastUpdated":1789023840000}'),d={name:"cs/arena-allocators.md"};function h(u,a,_,S,f,A){const t=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="jemalloc-tcmalloc-竞技场" tabindex="-1">jemalloc / tcmalloc 竞技场 <a class="header-anchor" href="#jemalloc-tcmalloc-竞技场" aria-label="Permalink to &quot;jemalloc / tcmalloc 竞技场&quot;">​</a></h1><div class="epigraph"><p>竞技场让每线程或每核几乎不共享空闲链：分配本地化，减少 malloc 锁，碎片在 arena 之间可能上升。</p><footer>—— 据 Evans, jemalloc 论文与手册；Google tcmalloc 设计文档</footer></div><p><a href="/cs/malloc-implementation">上一课</a>的单 arena 在多核上抢一把堆锁。缺口是 <strong>jemalloc/tcmalloc 的 arena/tcache</strong>：仍是用户态，不是内核 percpu。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>glibc 后来也有 per-thread 缓存，但历史上争用严重。jemalloc：多个 arena，线程绑定一个，size class extents。tcmalloc：per-thread cache + 中央页堆。缺口：fork 后子进程继承缓存要清；<a href="/cs/memcg">memcg</a> 看见的是 RSS，不管 arena 内部空闲；与 <a href="/cs/numa-mempolicy">NUMA</a> 可每节点 arena。本课不把两个库的调参字典抄完。</p><p><span class="marginnote">extent 在 jemalloc 里是连续虚存管理，类似内核的 vma 但在用户。tcmalloc 的 span 同类。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>线程首次 malloc：选 arena，填 tcache。释放：先回 tcache，溢出灌回 arena。对照内核 <a href="/cs/slab-allocator">slab</a> 的 per-cpu 杂志。对照 <a href="/cs/rss-multiqueue">RSS 网卡</a>：都是为了少跨核。对照 KSM：tcache 里的空闲不一定是零页。</p>',8)),(e(),s(p,null,{default:c(()=>[m(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E7%BA%BF%E7%A8%8B0%20tcache%22%5D%20--%3E%20A0%5B%22arena%200%22%5D%0A%20%20T1%5B%22%E7%BA%BF%E7%A8%8B1%20tcache%22%5D%20--%3E%20A1%5B%22arena%201%22%5D%0A%20%20A0%20--%3E%20MM%5B%22mmap%20%E5%90%91%E5%86%85%E6%A0%B8%22%5D%0A%20%20A1%20--%3E%20MM%0A"})]),fallback:c(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>竞技场用空间换时间：每 arena 自留空闲，RSS 可能比单堆大，但吞吐高。这是服务端默认换 glibc 的原因之一。不要写成 JVM GC 课。与 MTE：每个 arena 的释放仍要换标签。</p><p>调试：工具要懂 tcache，否则「free 了仍 RSS 高」是预期。</p><p>实现上：extent 保留虚址但不一定立刻要物理页，RSS 与 VSS 差一截。per-node arena 减少跨 NUMA 原子操作。后台 purge 线程才把空闲还内核。 读法上只引用<a href="/cs/malloc-implementation">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>jemalloc / tcmalloc 竞技场</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 mimalloc/snmalloc 的全部对照。不保证实时无锁分配器的最坏边界。内存进阶收口于检测工具：ASan 如何用影子内存。</p><p>版本字段会变，课序钉的是机制对象「jemalloc / tcmalloc 竞技场」，不是某一主线内核的结构体名。 后课默认：多线程堆用 arena/tcache 减锁。AddressSanitizer 的影子与红区，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>jemalloc/tcmalloc 用多 arena 与线程缓存减锁。</li><li>RSS 可能因空闲保留而更高。</li><li>ASan 机制是下一课。</li><li>出处：Evans jemalloc；tcmalloc 设计；Wilson 分配综述。</li></ul>',11))])}const b=o(d,[["render",h]]);export{E as __pageData,b as default};
